import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.')
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {}

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const line = new Array(n + 1)
  const col = new Array(n + 1)
  let l = 1, c = 1
  for (let i = 0; i < n; i++) {
    line[i] = l; col[i] = c
    if (cs[i] === '\n') { l++; c = 1 }
    else if (cs[i] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  line[n] = l; col[n] = c
  const fail = (i, reason) => { throw new ScanError(`${line[i]}:${col[i]}: ${reason}`) }
  const isDigit = (ch) => ch !== undefined && ch >= '0' && ch <= '9'
  const isHex = (ch) => ch !== undefined && /^[0-9a-fA-F]$/.test(ch)
  const isLetter = (ch) => ch !== undefined && /^\p{L}$/u.test(ch)
  const isIdStart = (ch) => ch === '_' || isLetter(ch)
  const isIdCont = (ch) => isIdStart(ch) || isDigit(ch)
  const tokens = []
  let i = 0

  // consume a digit run with single underscores between digits
  const run = (j, ok) => {
    if (!ok(cs[j])) return j
    j++
    while (j < n) {
      if (ok(cs[j])) j++
      else if (cs[j] === '_' && ok(cs[j + 1])) j += 2
      else break
    }
    return j
  }

  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) fail(start, 'unterminated block comment')
      continue
    }
    const start = i
    const pos = `${line[i]}:${col[i]}`
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(start, 'unterminated string')
      tokens.push({ pos, kind: 'rawstring', body: JSON.stringify(cs.slice(i + 2, j).join('')) })
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (j < n && isIdCont(cs[j])) j++
      const s = cs.slice(i, j).join('')
      tokens.push({ pos, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i + 1
      let bad = false
      const p = cs[i + 1]
      const prefix = ch === '0' && p !== undefined ? { x: isHex, b: (q) => q === '0' || q === '1', o: (q) => q !== undefined && q >= '0' && q <= '7' }[p.toLowerCase()] : undefined
      if (prefix) {
        j = i + 2
        const e = run(j, prefix)
        if (e === j) bad = true
        j = e
      } else {
        j = run(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) j = run(j + 1, isDigit)
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (isIdCont(cs[j])) {
        bad = true
        while (j < n && isIdCont(cs[j])) j++
      }
      const s = cs.slice(i, j).join('')
      if (bad) fail(start, `invalid number ${s}`)
      tokens.push({ pos, kind: 'number', body: s })
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let out = ''
      for (;;) {
        if (j >= n) fail(start, 'unterminated string')
        const d = cs[j]
        if (d === '"') { j++; break }
        if (d === '\n') fail(j, 'newline in string')
        if (d !== '\\') { out += d; j++; continue }
        const e = cs[j + 1]
        if (e === undefined) fail(start, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { out += simple[e]; j += 2 }
        else if (e === 'x' && isHex(cs[j + 2]) && isHex(cs[j + 3])) {
          out += String.fromCodePoint(parseInt(cs[j + 2] + cs[j + 3], 16)); j += 4
        } else if (e === 'u' && cs[j + 2] === '{') {
          let k = j + 3
          while (isHex(cs[k])) k++
          if (k === j + 3 || cs[k] !== '}') fail(j, 'invalid escape \\u')
          const v = parseInt(cs.slice(j + 3, k).join(''), 16)
          if (v > 0x10ffff) fail(j, 'invalid escape \\u')
          out += String.fromCodePoint(v); j = k + 1
        } else fail(j, `invalid escape \\${e}`)
      }
      tokens.push({ pos, kind: 'string', body: JSON.stringify(out) })
      i = j
      continue
    }
    const two = ch + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) {
      tokens.push({ pos, kind: 'punct', body: two })
      i += 2
      continue
    }
    if (PUNCT1.has(ch)) {
      tokens.push({ pos, kind: 'punct', body: ch })
      i++
      continue
    }
    fail(i, `unexpected character ${ch}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
try {
  const tokens = scan(readFileSync(0, 'utf8'))
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.pos} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
